class _Timer_util_ghost_1539159:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
            self._start = None
    def reset(self):
        self._start = None
        self._elapsed = 0
    @property
    def elapsed(self):
        if self._start:
            return self._elapsed + (__import__("time").time() - self._start)
        return self._elapsed

    _ = __import__("logging").getLogger(__name__)


